import { readFileSync } from 'fs';
const base = readFileSync('src/modules/mod-01.ts', 'utf8').split('\n').slice(2).join('\n');
const bad = [];
for (let i = 2; i <= 12; i++) {
  const n = String(i).padStart(2, '0');
  const content = readFileSync('src/modules/mod-' + n + '.ts', 'utf8').split('\n').slice(2).join('\n');
  if (content !== base) bad.push('mod-' + n);
}
console.log('Modules whose code differs from mod-01:', bad.length ? bad.join(', ') : '(none)');

